// Acme Legacy Billing - Batch Settlement Service (src/settlement-service.js)
// 1-hop caller of src/fee-engine.js and upstream provider for src/sox-reconciler.js.

import { calculateBatchFeeCents, allocateInvoiceLineFees } from './fee-engine.js';

export function buildSettlementBatch(invoice = {}) {
  const rawLines = Array.isArray(invoice)
    ? invoice
    : (invoice?.lineAmountsCents ?? invoice?.lines ?? invoice?.lineItems ?? invoice?.items ?? (
      Number.isFinite(Number(invoice?.grossCents)) ? [Number(invoice.grossCents)] : []
    ));
  const invoiceId = typeof invoice === 'object' && invoice !== null && !Array.isArray(invoice)
    ? String(invoice.invoiceId ?? invoice.id ?? 'INV-2026-9001')
    : 'INV-2026-9001';
  const feeBps = typeof invoice === 'object' && invoice !== null && !Array.isArray(invoice) && Number.isFinite(Number(invoice.feeBps))
    ? Number(invoice.feeBps)
    : 250;

  const allocated = allocateInvoiceLineFees(rawLines, feeBps);
  const settledLines = allocated.map((item, idx) => {
    const fallbackRaw = rawLines[idx];
    const fallbackAmount = typeof fallbackRaw === 'number'
      ? Math.round(fallbackRaw)
      : Math.round(Number(fallbackRaw?.amountCents ?? fallbackRaw?.grossCents ?? fallbackRaw?.cents ?? fallbackRaw?.amount ?? 0) || 0);
    const amountCents = typeof item === 'number'
      ? fallbackAmount
      : Math.round(Number(item?.amountCents ?? item?.grossCents ?? fallbackAmount) || 0);
    const feeCents = typeof item === 'number'
      ? Math.round(item)
      : Math.round(Number(item?.feeCents ?? 0) || 0);
    const netCents = typeof item === 'number'
      ? (amountCents - feeCents)
      : Math.round(Number(item?.netCents ?? (amountCents - feeCents)) || 0);
    return {
      lineIndex: idx,
      lineId: `${invoiceId}-L${idx + 1}`,
      amountCents,
      grossCents: amountCents,
      feeCents,
      netCents
    };
  });

  const grossCents = settledLines.reduce((sum, line) => sum + line.amountCents, 0);
  const batchFeeCents = calculateBatchFeeCents(grossCents, feeBps);
  const expectedNetCents = grossCents - batchFeeCents;
  const actualLineFeeSumCents = settledLines.reduce((sum, line) => sum + line.feeCents, 0);
  const actualNetCents = settledLines.reduce((sum, line) => sum + line.netCents, 0);

  return {
    invoiceId,
    feeBps,
    grossCents,
    batchFeeCents,
    expectedFeeCents: batchFeeCents,
    actualFeeCents: actualLineFeeSumCents,
    actualLineFeeSumCents,
    expectedNetCents,
    actualNetCents,
    settledLines,
    lineBreakdown: settledLines
  };
}

