// Acme Legacy Billing - Inbound Webhook Handler (src/webhook-handler.js)
// Scoped to Work Order WO-102 (disjoint from WO-101 settlement fee cone).

import crypto from 'node:crypto';

export function handleBillingWebhook(payload = {}, signatureHeader = '', secret = 'acme-webhook-signing-key') {
  const rawBody = typeof payload === 'string' ? payload : JSON.stringify(payload ?? {});
  const normalizedHeader = String(signatureHeader || '').trim().replace(/^sha256=/i, '');
  const expectedHex = crypto.createHmac('sha256', String(secret)).update(rawBody, 'utf8').digest('hex');
  const providedBuf = Buffer.from(normalizedHeader, 'utf8');
  const expectedBuf = Buffer.from(expectedHex, 'utf8');
  const verified = providedBuf.length === expectedBuf.length && crypto.timingSafeEqual(providedBuf, expectedBuf);

  return {
    accepted: verified,
    eventType: typeof payload === 'object' && payload !== null ? String(payload.type || 'billing.ping') : 'billing.raw',
    verified
  };
}

