// Acme Legacy Billing - Service Entry Choke-Point (src/server.js)
// Reserved for Orchestrator integration across WO-101, WO-102, and WO-103.

import { buildSettlementBatch } from './settlement-service.js';
import { reconcileSettlementLedger } from './sox-reconciler.js';
import { handleBillingWebhook } from './webhook-handler.js';
import { listTenantInvoices } from './invoice-list.js';

export function routeBillingOperation(operation, payload = {}) {
  if (operation === 'settlement.preview') {
    return buildSettlementBatch(payload.invoice ?? payload);
  }
  if (operation === 'settlement.reconcile') {
    return reconcileSettlementLedger(payload.invoice ?? payload);
  }
  if (operation === 'webhook.ingest') {
    return handleBillingWebhook(payload.body ?? payload, payload.signatureHeader ?? '');
  }
  if (operation === 'invoices.list') {
    return listTenantInvoices(payload.items ?? [], payload.cursor ?? null, payload.pageSize ?? 25);
  }
  throw new Error(`Unsupported billing operation: ${String(operation)}`);
}

