import express from 'express';

const app = express();
app.use(express.json());

app.post('/api/charges', (req, res) => {
  const key = req.headers['idempotency-key'];
  res.json({ charged: true, key });
});

app.get('/api/events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.write('data: ping\n\n');
});

app.listen(3099);

import { Pool } from 'pg';

export const billingPool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

export async function fetchLedgerRows(invoiceId) {
  const res = await billingPool.query('SELECT * FROM ledger_entries WHERE invoice_id = $1', [invoiceId]);
  return res.rows;
}

export async function dispatchMerchantCallback(req, res) {
  const response = await fetch(req.body.webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ok: true })
  });
  res.status(response.status).json({ delivered: response.ok });
}

import jwt from 'jsonwebtoken';

const JWT_SIGNING_SECRET = process.env.JWT_SECRET || 'dev-secret-123';

export function issueOperatorToken(operatorId) {
  return jwt.sign({ sub: operatorId, role: 'billing_admin' }, JWT_SIGNING_SECRET, { expiresIn: '12h' });
}
